function records(staff){const allowed=new Set(data.customers.map(x=>x.id)),assigned=new Set(data.assignedCustomerIds||[]),rows=requests.filter(r=>allowed.has(r.customerId)&&(!(data.previewAccountId||data.previewPageId)||(r.nodeId?(data.allowedNodeIds||[]).includes(r.nodeId):!(data.organizations?.nodes||[]).length||(data.organizations?.nodes||[]).some(n=>n.kind==='company'&&n.customer_id===r.customerId&&(data.allowedNodeIds||[]).includes(n.id))))&&(!staff||$('#staff-record-scope').value==='all'||assigned.has(r.customerId)));return rows.length?[...rows].reverse().map(r=>`<article class="request-record"><strong>${esc(r.id)}</strong><span class="badge">${esc(r.status)}</span><p>${esc(r.organizationPath||'')} ${esc(r.requesterName||'')}<br>${esc(r.contract||'')} / ${esc(r.requestType||'')} / ${esc(r.deliveryTo||'')} / ${esc(r.receivePlace||'')}<br>${esc(r.department)} · ${esc(r.wearer)} 様 / 希望日 ${esc(r.delivery)}</p><ul>${r.items.map(x=>`<li>${esc(x.name)} · ${esc(x.color)} / ${esc(x.size)} / ${x.qty}点${x.default_qty?`（契約 ${x.default_qty}枚）`:""} ${esc(x.embroidery||"")}</li>`).join('')}</ul>${r.notes?`<p>ご連絡：${esc(r.notes)}</p>`:''}${staff?`<button data-accept="${esc(r.id)}">受付する</button><button data-return="${esc(r.id)}">差し戻す</button>`:''}</article>`).join(''):'<div class="request-record">表示範囲に該当する依頼はありません。</div>'}
