function renderWebPublication(){const id=Number($('#org-root-customer').value),panel=$('#web-publication-panel');if(!panel)return;panel.hidden=mode!=='web-settings'||!id;const select=$('#web-publication-scope'),old=select.value;select.innerHTML=(!data.manageCommonCustomerIds||data.manageCommonCustomerIds.includes(id)?'<option value="">会社全体の共通設定</option>':'')+(data.organizations?.nodes||[]).filter(n=>n.customer_id===id&&n.kind!=='company'&&(!data.allowedNodeIds||data.allowedNodeIds.includes(n.id))).map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('');if([...select.options].some(o=>o.value===old))select.value=old;const p=publicationProfile();$('#web-publication-status').textContent=p?(p.status==='published'?'依頼画面に反映済み':p.status==='paused'?'受付停止中':'依頼画面へ未反映'):'';for(const key of ['web-publish-common','web-pause-common'])$('#'+key).disabled=!p||busy}
async function publishCommon(action){const p=publicationProfile(),customer=Number($('#org-root-customer').value);if(!p||busy)return;if(window.WebRequestOrganization?.hasChanges())return notify('先にWEB依頼の設定を保存してください。');if(action==='pause'&&!confirm('選択した対象の受付を停止しますか？'))return;busy=true;renderWebPublication();try{await api({action,customer_id:customer,node_id:p.node_id||null,version:p.version,config:cleanConfig(p.draft),inheritance_mode:p.draft_mode||'inherit',parent_config:p.node_id?cleanConfig(p.parent_config):null});await loadSettings();notify(action==='pause'?'受付を停止しました。':'保存済みの契約・制服を依頼画面へ反映しました。')}catch(e){notify(e.message)}finally{busy=false;renderWebPublication()}}
