document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab)tab(b.dataset.tab);if(b.dataset.add){if(data.previewCanRequest===false)return notify('この利用者は閲覧のみです。');const p=products.find(x=>x.id===b.dataset.add),size=document.querySelector(`[data-size="${p.id}"]`).value,qty=Number(document.querySelector(`[data-qty="${p.id}"]`).value);if(!Number.isInteger(qty)||qty<1||qty>99)return notify('数量は1〜99で入力してください。');const old=cart.find(x=>x.id===p.id&&x.size===size);if(old&&old.qty+qty>99)return notify('同じ商品の数量は99点までです。');if(old)old.qty+=qty;else cart.push({id:p.id,name:p.name,color:p.color,size,qty,customer_product_id:p.customer_product_id,product_id:p.product_id,embroidery:p.embroidery,default_qty:p.contract_qty});renderCart();notify('ご依頼内容に追加しました。')}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);renderCart()}if(b.dataset.accept||b.dataset.return){const r=requests.find(x=>x.id===(b.dataset.accept||b.dataset.return));r.status=b.dataset.accept?'受付済み':'差し戻し';save();renderRecords()}});
