 $('#registered-contracts').innerHTML='<h4>部署・契約の作成・編集</h4><label class="check"><input type="checkbox" id="site-no-department"> 部署なしの契約も作成する（割り当て先へ直接登録）</label><p class="small">部署のカードから直接編集できます。✎で部署名の変更、契約をダブルクリックすると契約と制服の編集、「＋契約」で契約の追加です。契約を右クリックしてコピーし、貼り付け先の部署を右クリックしてください。ドラッグでも複製できます（Ctrl+C／Ctrl+Vも使用可）。</p><div class="dept-grid">'+rows.map(d=>`<section class="dept-card ${d.id===$('#department').value&&deptPanel?'selected':''}" data-dept="${esc(d.id)}" tabindex="0" aria-label="${esc(d.name)}">${d.no_department?'<div class="dept-head"><strong>部署なしの契約</strong></div>':head(d)}<ul class="dept-contracts">${d.contracts.length?d.contracts.map(k=>line(d,k)).join(''):'<li class="dept-empty">契約なし</li>'}</ul><button type="button" class="dept-mut dept-add-contract" data-dept-new-contract="${esc(d.id)}" ${locked?'disabled':''}>＋契約</button></section>`).join('')+(deptAdding?`<section class="dept-card dept-new"><div class="dept-head dept-rename"><input class="dept-new-input" maxlength="80" placeholder="部署名" aria-label="追加する部署名"><button type="button" class="primary" data-dept-add-ok>追加</button><button type="button" data-dept-add-cancel>取消</button></div></section>`:`<button type="button" class="dept-card dept-new dept-mut" data-dept-add ${locked?'disabled':''}>＋部署</button>`)+'</div>'+(rows.length?'':'<p class="small">部署・契約はまだありません。「＋部署」から登録してください。</p>');
